   273  #define XDIGIT(c) ((c) <= '9' ? (c) - '0' : ((c) & 0x4F) - 'A' + 10)
   274  #define HEXCHAR(s) ((XDIGIT (s[1]) << 4) + XDIGIT (s[2]))
