   276  static gssize
   277  uri_decoder (gchar       **out,
   278               const gchar  *illegal_chars,
   279               const gchar  *start,
   280               gsize         length,
   281               gboolean      just_normalize,
   282               gboolean      www_form,
   283               GUriFlags     flags,
   284               GUriError     parse_error,
   285               GError      **error)
   286  {
   287    gchar c;
   288    GString *decoded;
   289    const gchar *invalid, *s, *end;
   290    gssize len;
   291
   292    if (!(flags & G_URI_FLAGS_ENCODED))
   293      just_normalize = FALSE;
   294
   295    decoded = g_string_sized_new (length + 1);
   296    for (s = start, end = s + length; s < end; s++)
   297      {
   298        if (*s == '%')
   299          {
   300            if (s + 2 >= end ||
   301                !g_ascii_isxdigit (s[1]) ||
   302                !g_ascii_isxdigit (s[2]))
   303              {
   304                /* % followed by non-hex or the end of the string; this is an error */
   305                if (!(flags & G_URI_FLAGS_PARSE_RELAXED))
   306                  {
   307                    g_set_error_literal (error, G_URI_ERROR, parse_error,
   308                                         /* xgettext: no-c-format */
   309                                         _("Invalid %-encoding in URI"));
   310                    g_string_free (decoded, TRUE);
   311                    return -1;
   312                  }
   313
   314                /* In non-strict mode, just let it through; we *don't*
   315                 * fix it to "%25", since that might change the way that
   316                 * the URI's owner would interpret it.
   317                 */
   318                g_string_append_c (decoded, *s);
   319                continue;
   320              }
   321
   322            c = HEXCHAR (s);
   323            if (illegal_chars && strchr (illegal_chars, c))
   324              {
   325                g_set_error_literal (error, G_URI_ERROR, parse_error,
   326                                     _("Illegal character in URI"));
   327                g_string_free (decoded, TRUE);
   328                return -1;
   329              }
   330            if (just_normalize && !g_uri_char_is_unreserved (c))
   331              {
   332                /* Leave the % sequence there but normalize it. */
   333                g_string_append_c (decoded, *s);
   334                g_string_append_c (decoded, g_ascii_toupper (s[1]));
   335                g_string_append_c (decoded, g_ascii_toupper (s[2]));
   336                s += 2;
   337              }
   338            else
   339              {
   340                g_string_append_c (decoded, c);
   341                s += 2;
   342              }
   343          }
   344        else if (www_form && *s == '+')
   345          g_string_append_c (decoded, ' ');
   346        /* Normalize any illegal characters. */
   347        else if (just_normalize && (!g_ascii_isgraph (*s)))
   348          g_string_append_printf (decoded, "%%%02X", (guchar)*s);
   349        else
   350          g_string_append_c (decoded, *s);
   351      }
   352
   353    len = decoded->len;
   354    g_assert (len >= 0);
   355
   356    if (!(flags & G_URI_FLAGS_ENCODED) &&
   357        !g_utf8_validate (decoded->str, len, &invalid))
   358      {
   359        g_set_error_literal (error, G_URI_ERROR, parse_error,
   360                             _("Non-UTF-8 characters in URI"));
   361        g_string_free (decoded, TRUE);
   362        return -1;
   363      }
   364
   365    if (out)
   366      *out = g_string_free (decoded, FALSE);
   367    else
   368      g_string_free (decoded, TRUE);
   369
   370    return len;
